<?php require __DIR__.'/../config.php';require __DIR__.'/../functions.php';requireAdmin();$cars=db()->query('SELECT * FROM cars ORDER BY active DESC,budget,seats,name')->fetchAll();adminTop('Cars & Fleet','cars');?><div class="section-head"><div><p class="muted">Manage cars, tempo travellers and buses. Upload the exact real images and multiple angle frames for the 360 viewer.</p></div><a class="btn primary" href="car_form.php">+ Add Vehicle</a></div><div class="table-wrap"><table><thead><tr><th>Image</th><th>Vehicle</th><th>Seats</th><th>Budget</th><th>Price</th><th>Gallery</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($cars as $c):$q=db()->prepare('SELECT COUNT(*) FROM car_images WHERE car_id=?');$q->execute([$c['id']]);$n=(int)$q->fetchColumn();?><tr><td><img class="thumb" src="<?=e($c['image_url'])?>" onerror="this.src='https://placehold.co/120x80/1c1410/d4a373?text=Car'"></td><td><b><?=e($c['name'])?></b><small><?=e($c['type'])?></small></td><td><?=e($c['seats'])?></td><td><?=e($c['budget'])?></td><td><?=money((float)$c['day_price'])?><small><?=money((float)$c['km_price'])?>/km</small></td><td><?=$n?> frames</td><td><span class="status <?=$c['active']?'confirmed':'cancelled'?>"><?=$c['active']?'Active':'Hidden'?></span></td><td class="actions"><a class="btn ghost mini" href="car_form.php?id=<?=$c['id']?>">Edit</a><form method="post" action="car_delete.php" onsubmit="return confirm('Delete this vehicle? Existing bookings prevent destructive deletion, so it may be hidden instead.')"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$c['id']?>"><button class="btn danger mini">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php adminBottom(); ?>